const x = {{ json . }};
if(x.confirmation_manuelle === "oui") x.confirmation_manuelle=true; else if(x.confirmation_manuelle === "non") x.confirmation_manuelle=false;
if(x.contradiction === "oui") x.contradiction=true; else if(x.contradiction === "non" || x.contradiction == null) x.contradiction=false;
if(typeof x.dossier_id!=="string" || !/^[a-z0-9][a-z0-9-]{0,63}$/.test(x.dossier_id)) throw new Error("invalid_dossier_id");
if(x.confirmation_manuelle!==true) throw new Error("manual_confirmation_required");
for(const f of ["entreprise","sujet","faits","source_ref"]) if(typeof x[f]!=="string" || !x[f].trim() || x[f].length>8000) throw new Error("invalid_input_"+f);
if(x.brouillon!=null && (typeof x.brouillon!=="string" || x.brouillon.length>16000)) throw new Error("invalid_draft");
const draft = x.brouillon && x.brouillon.trim() ? x.brouillon.trim() : ["BROUILLON À RELIRE",x.sujet,"Faits fournis :",x.faits,"Source : "+x.source_ref,"Aucune publication effectuée."].join("\n\n");
return {id:x.dossier_id,entreprise:x.entreprise,role:"contenu",etat:"brouillon",sujet:x.sujet,faits:x.faits,source_ref:x.source_ref,brouillon:draft,external_effect:false};

import { callTool } from './tools/nats_bridge.ts';
const input={{ json . }};
const data={{ json .record }};
if(!data||typeof data!=="object") throw new Error("broker_save_data_invalid");
const expected_revision=input.expected_revision==null||input.expected_revision===""?0:Number(input.expected_revision);
if(!Number.isSafeInteger(expected_revision)||expected_revision<0) throw new Error("expected_revision_invalid");
const response=await callTool("recipe--application_data_v1",{operation:"save",namespace:"cib-contenu",record_key:data.id,data,expected_revision});
const payload=response&&response.data?response.data:response;
if(!payload||!payload.record||typeof payload.record!=="object") throw new Error("broker_record_invalid");
const item=payload.record;
if(item.namespace!=="cib-contenu"||item.key!==data.id) throw new Error("broker_record_identity_invalid");
if(!Number.isSafeInteger(item.revision)||item.revision<0) throw new Error("broker_revision_invalid");
if(!item.data||typeof item.data!=="object") throw new Error("broker_record_data_invalid");
const permissions=item.permissions;
if(!permissions||typeof permissions.can_read!=="boolean"||typeof permissions.can_write!=="boolean"||typeof permissions.can_manage!=="boolean") throw new Error("broker_permissions_invalid");
const shares=Array.isArray(item.shares)?item.shares:[];const permissions_summary="Lecture : "+(permissions.can_read===true?"oui":"non")+" · Modification : "+(permissions.can_write===true?"oui":"non")+" · Partage : "+(permissions.can_manage===true?"oui":"non");const share_count=shares.length;
return {record:item.data,content:JSON.stringify(item.data,null,2),revision:item.revision,owner_user_id:typeof item.owner_user_id==="string"?item.owner_user_id:"",permissions,permissions_summary,shares,share_count,path:"/company-in-a-box/contenu/"+item.key};
